-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Oficinas de Impressão 3D e Robótica' and a.numero = 7
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 7 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 07', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 07 (10 questões discursivas)',
      '/MATERIAIS/RIO_DO_SUL_MAIS_TECH/OFICINAS_IMPRESSAO_3D_ROBOTICA/ATIVIDADES/ATIVIDADE-PRATICA-AULA-07.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Explique o que é o Blockly e por que ele é chamado de linguagem visual.', 0.2, 'O Blockly é uma linguagem de programação visual: cada comando é um bloco que se encaixa em outro, sem precisar digitar código em texto.', 'Nota cheia: diz que é uma linguagem de blocos e que é visual por usar blocos encaixáveis. Metade: só uma dessas ideias. Zero: conceito errado ou em branco.'),
      (v_atividade, 1, 2, 'Diga como os blocos se relacionam entre si para formar um programa.', 0.4, 'Os blocos se encaixam um no outro e o programa é lido e executado de cima para baixo, na ordem em que estão encaixados (sequência); alguns blocos, como repetição e condição, guardam outros blocos dentro deles.', 'Nota cheia: fala do encaixe e da execução de cima para baixo (ou da ordem). Metade: só um dos dois. Zero: sem relação.'),
      (v_atividade, 1, 3, 'Cite duas vantagens de começar a programar um robô por blocos em vez de texto.', 0.4, 'Exemplos: é mais fácil de entender e montar; não exige decorar a escrita dos comandos; evita erros de digitação e de sintaxe; dá para ver a lógica do programa; permite testar blocos aos poucos.', 'Nota cheia: duas vantagens coerentes. Metade: uma. Zero: nenhuma coerente.'),
      (v_atividade, 2, 1, 'Diga em que ordem o robô executa os blocos de um programa.', 0.2, 'De cima para baixo, um bloco depois do outro, na ordem em que estão encaixados.', 'Nota cheia: diz de cima para baixo (ou na ordem de encaixe). Metade: diz só "em ordem" sem indicar o sentido. Zero: errado ou em branco.'),
      (v_atividade, 2, 2, 'Explique o que o robô fará com o programa recebido e por que isso não é o que se queria.', 0.4, 'O robô primeiro gira 90° à direita, depois anda 2 s, anda mais 1 s e para. Isso não é o que se queria porque o giro veio antes de o robô andar o primeiro trecho: a ordem dos blocos mudou o trajeto.', 'Nota cheia: descreve a execução na ordem recebida (gira primeiro) e relaciona a ordem ao trajeto errado. Metade: só descreve a execução ou só diz que a ordem está errada. Zero: sem relação.'),
      (v_atividade, 2, 3, 'Escreva a ordem correta dos blocos para andar 2 s, girar 90° à direita, andar 1 s e parar.', 0.4, '1) andar 2 s; 2) girar 90° à direita; 3) andar 1 s; 4) parar.', 'Nota cheia: os quatro blocos na ordem certa. Metade: os quatro blocos com uma troca de posição. Zero: ordem muito diferente ou em branco.'),
      (v_atividade, 3, 1, 'Explique o que faz o bloco de repetição e que problema ele evita.', 0.2, 'O bloco de repetição executa os blocos que estão dentro dele o número de vezes indicado. Evita copiar o mesmo grupo de blocos várias vezes.', 'Nota cheia: explica que repete os blocos de dentro e que evita copiar blocos. Metade: só um. Zero: errado ou em branco.'),
      (v_atividade, 3, 2, 'Escreva o programa do quadrado usando um bloco de repetição, dizendo quantas vezes repetir e quais blocos ficam dentro.', 0.4, 'Repetir 4 vezes: andar (um lado) e girar 90°. Os dois blocos, andar e girar, ficam dentro da repetição.', 'Nota cheia: repetir 4 vezes com andar e girar 90° dentro. Metade: acerta os blocos de dentro mas erra o número de repetições (ou o inverso). Zero: não usa repetição ou em branco.'),
      (v_atividade, 3, 3, 'Explique por que o ajuste do tamanho do quadrado fica mais fácil com a repetição.', 0.4, 'Com a repetição, o tamanho do lado fica em um único bloco "andar"; basta mudar esse valor uma vez, em vez de alterar quatro blocos copiados, o que reduz erros e economiza tempo.', 'Nota cheia: diz que se altera o valor em um só lugar e que isso evita erro ou poupa trabalho. Metade: só uma dessas ideias. Zero: sem relação.'),
      (v_atividade, 4, 1, 'Explique para que serve um bloco de condição em um programa de robô.', 0.2, 'A condição faz o robô decidir o que fazer a partir de uma situação (como a leitura de um sensor): se algo é verdadeiro, executa uma ação; senão, executa outra.', 'Nota cheia: diz que serve para decidir a ação conforme uma situação ou sensor. Metade: fala só de "se ... então" sem explicar a decisão. Zero: errado ou em branco.'),
      (v_atividade, 4, 2, 'Escreva a condição "se ... então ... senão ..." para o robô parar com algo perto e andar com o caminho livre.', 0.4, 'Se distância (do sensor) menor que um valor (por exemplo, 15 cm), então parar; senão, andar para frente.', 'Nota cheia: condição com o teste do sensor, ação de parar no "então" e andar no "senão". Metade: estrutura certa com as ações trocadas ou sem o valor da distância. Zero: sem condição ou em branco.'),
      (v_atividade, 4, 3, 'Diferencie condição de sequência, dando uma situação em que cada uma é usada.', 0.4, 'Sequência: os blocos executam um após o outro, sempre do mesmo jeito (por exemplo, andar, girar, andar). Condição: o robô escolhe entre caminhos conforme o sensor (por exemplo, parar se houver obstáculo).', 'Nota cheia: diferencia as duas e dá uma situação para cada. Metade: diferencia sem dar situações, ou dá a situação de só uma. Zero: trocadas ou em branco.'),
      (v_atividade, 5, 1, 'Explique o que é uma trajetória e o que são os pontos que o robô visita.', 0.2, 'Trajetória é o caminho que o robô percorre; ele é formado por pontos que o robô visita em ordem.', 'Nota cheia: define trajetória como caminho e pontos visitados em ordem. Metade: só uma das ideias. Zero: errado ou em branco.'),
      (v_atividade, 5, 2, 'Indique, para cada trecho do trajeto, a distância e a direção que precisam ser definidas.', 0.4, 'Para cada trecho é preciso definir a distância (por tempo ou por voltas de roda) e a direção (o ângulo do giro). Ex.: trecho longo, andar 2 s; curva, girar 90° à direita; trecho curto, andar 1 s.', 'Nota cheia: cita distância e direção (ângulo) para os trechos. Metade: cita só um dos dois. Zero: sem relação.'),
      (v_atividade, 5, 3, 'Escreva o programa em blocos do trajeto em L, com valores de tempo e ângulo.', 0.4, 'Exemplo: andar 2 s; girar 90° à direita; andar 1 s; parar.', 'Nota cheia: trecho longo, giro de 90° à direita, trecho curto e parar, em ordem, com valores. Metade: falta um bloco ou os valores. Zero: ordem sem lógica ou em branco.'),
      (v_atividade, 6, 1, 'Diga quantos giros o percurso em U exige e de quantos graus é cada um.', 0.2, 'Dois giros, de 90° cada, os dois para a direita.', 'Nota cheia: dois giros de 90°. Metade: acerta a quantidade ou o ângulo, mas não os dois. Zero: errado ou em branco.'),
      (v_atividade, 6, 2, 'Escreva o programa em blocos do percurso em U, em ordem, com tempos de exemplo.', 0.4, 'Exemplo: andar 2 s; girar 90° à direita; andar 1 s; girar 90° à direita; andar 2 s; parar.', 'Nota cheia: andar, dois giros de 90° à direita separados por um trecho, andar de volta e parar. Metade: falta um bloco ou o trecho do meio. Zero: não forma um U ou em branco.'),
      (v_atividade, 6, 3, 'Explique como se mede o tamanho de um trecho para o robô andar a distância certa.', 0.4, 'A distância pode ser medida pelo tempo que o robô anda (segundos) ou pelas voltas da roda; define-se o valor, testa-se e ajusta-se até o trecho ficar do tamanho marcado no chão.', 'Nota cheia: cita tempo ou voltas de roda e o teste com ajuste. Metade: cita só tempo ou voltas de roda. Zero: sem relação.'),
      (v_atividade, 7, 1, 'Explique o que é o erro acumulado no percurso de um robô.', 0.2, 'É a diferença entre o percurso planejado e o real que vai aumentando a cada trecho ou teste, porque pequenos desvios do robô se somam.', 'Nota cheia: diz que é uma diferença ou desvio que se acumula. Metade: só fala que o robô erra, sem a ideia de acúmulo. Zero: errado ou em branco.'),
      (v_atividade, 7, 2, 'Cite duas causas que fazem o robô não repetir o mesmo percurso.', 0.4, 'Exemplos: patinação das rodas; bateria fraca (menos velocidade); piso diferente; roda desalinhada.', 'Nota cheia: duas causas coerentes. Metade: uma. Zero: nenhuma coerente.'),
      (v_atividade, 7, 3, 'Explique por que a equipe deve testar e ajustar os valores do programa em vez de confiar nos primeiros números.', 0.4, 'Porque o robô real não repete exatamente o planejado; só testando se vê o desvio e só ajustando os valores (tempos e ângulos) o trajeto fica correto.', 'Nota cheia: diz que o robô real desvia e que o teste e o ajuste corrigem. Metade: só uma dessas ideias. Zero: sem relação.'),
      (v_atividade, 8, 1, 'Escreva o programa em blocos: repetir sempre, com a condição de distância menor que 15 cm.', 0.2, 'Repetir sempre: se distância < 15 cm então parar e girar 90°, senão andar para frente.', 'Nota cheia: repetição, condição com a distância e as duas ações. Metade: falta a repetição ou o "senão". Zero: sem condição ou em branco.'),
      (v_atividade, 8, 2, 'Explique o que o robô faz quando a distância é menor que 15 cm e o que faz quando é maior.', 0.4, 'Com distância menor que 15 cm, o robô para e gira 90° para sair da frente do obstáculo; com distância maior, ele segue andando para frente.', 'Nota cheia: descreve as duas situações. Metade: descreve só uma. Zero: errado ou em branco.'),
      (v_atividade, 8, 3, 'Explique por que o sensor, o controlador e o atuador precisam trabalhar em conjunto nesse programa.', 0.4, 'O sensor mede a distância, o controlador lê a medida e decide pela condição, e o atuador (motor) executa a ação de parar, girar ou andar. Sem um deles, o robô não percebe, decide ou se move.', 'Nota cheia: dá o papel de sensor, controlador e atuador no programa. Metade: dá o papel de dois deles. Zero: um ou nenhum.'),
      (v_atividade, 9, 1, 'Explique o que é depurar um programa.', 0.2, 'Depurar é encontrar e corrigir o que faz o programa se comportar diferente do esperado, testando e ajustando.', 'Nota cheia: encontrar e corrigir o comportamento errado. Metade: só uma dessas ideias. Zero: errado ou em branco.'),
      (v_atividade, 9, 2, 'Escreva os passos da depuração que a equipe deveria seguir, em ordem.', 0.4, '1) executar e observar onde o comportamento foge do esperado; 2) testar um bloco de cada vez (ou um trecho curto); 3) alterar um valor por vez e testar de novo; 4) anotar o que funcionou.', 'Nota cheia: pelo menos três dos quatro passos em ordem coerente. Metade: dois passos. Zero: um ou nenhum.'),
      (v_atividade, 9, 3, 'Explique por que se deve alterar um valor por vez e anotar o que funcionou.', 0.4, 'Alterando um valor por vez, a equipe sabe qual mudança causou o efeito, e anotar o que funcionou permite repetir a solução no projeto. Mudar tudo de uma vez esconde a causa do problema.', 'Nota cheia: explica que um valor por vez mostra a causa e que a anotação permite repetir. Metade: só uma dessas ideias. Zero: sem relação.'),
      (v_atividade, 10, 1, 'Indique qual parte do robô sente o obstáculo, qual decide e qual se movimenta.', 0.2, 'O sensor sente o obstáculo, o controlador decide e o atuador (motor) movimenta o robô.', 'Nota cheia: as três partes certas. Metade: duas. Zero: uma ou nenhuma.'),
      (v_atividade, 10, 2, 'Descreva a lógica do programa para o robô seguir a rota e reagir a um obstáculo.', 0.4, 'Repetir sempre: se o sensor detectar obstáculo à frente, então parar (e esperar ou desviar); senão, seguir a rota programada (andar, girar nos pontos do trajeto) até o ponto final e parar.', 'Nota cheia: rota em sequência e condição de obstáculo com a ação de parar ou desviar. Metade: só a rota ou só a condição. Zero: sem lógica ou em branco.'),
      (v_atividade, 10, 3, 'Liste três informações que a equipe deve registrar na entrega da aula.', 0.4, 'Exemplos: o programa em blocos (captura ou foto); o robô cumprindo o trajeto; os ajustes feitos (valores que mudaram e por quê); resultado dos testes.', 'Nota cheia: três informações coerentes com a entrega da aula. Metade: duas. Zero: uma ou nenhuma.');
end $$;
